import 'package:animations/animations.dart';
import 'package:flutter/material.dart';

class OpenContainerTransformDemo extends StatelessWidget {
  const OpenContainerTransformDemo({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Container Transform Demo')),
      body: ListView.builder(
        itemCount: 5,
        itemBuilder: (context, index) {
          return OpenContainer<bool>(
            transitionType: ContainerTransitionType.fadeThrough, // 전환 타입 설정
            closedElevation: 0.0,
            closedBuilder: (BuildContext context, VoidCallback action) {
              // 닫힌 상태 (리스트 타일)
              return ListTile(
                onTap: action, // action을 호출하면 openBuilder로 전환 시작
                leading: const Icon(Icons.article),
                title: Text('게시물 제목 ${index + 1}'),
                subtitle: const Text('탭하여 상세 정보 보기'),
              );
            },
            openBuilder: (BuildContext context, VoidCallback action) {
              // 열린 상태 (상세 화면)
              return _DetailScreen(index: index + 1);
            },
          );
        },
      ),
    );
  }
}

class _DetailScreen extends StatelessWidget {
  final int index;
  const _DetailScreen({required this.index});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('상세 화면 $index'),
      ),
      body: Center(
        child: Padding(
          padding: const EdgeInsets.all(16.0),
          child: Text(
            '이것은 게시물 $index의 상세 내용입니다. 리스트 타일에서 부드럽게 확장되었습니다.',
            style: Theme.of(context).textTheme.headlineSmall,
            textAlign: TextAlign.center,
          ),
        ),
      ),
    );
  }
}

import 'package:animations/animations.dart';
import 'package:flutter/material.dart';

class FadeThroughTransitionDemo extends StatefulWidget {
  const FadeThroughTransitionDemo({super.key});

  @override
  State<FadeThroughTransitionDemo> createState() => _FadeThroughTransitionDemoState();
}

class _FadeThroughTransitionDemoState extends State<FadeThroughTransitionDemo> {
  int _selectedIndex = 0;

  final List<Widget> _pages = const [
    _PageContent(icon: Icons.home, label: '홈 화면'),
    _PageContent(icon: Icons.settings, label: '설정'),
    _PageContent(icon: Icons.person, label: '프로필'),
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Fade Through Demo')),
      body: PageTransitionSwitcher(
        duration: const Duration(milliseconds: 500),
        transitionBuilder: (child, animation, secondaryAnimation) {
          return FadeThroughTransition(
            animation: animation,
            secondaryAnimation: secondaryAnimation,
            child: child,
          );
        },
        // key가 변경될 때마다 전환이 발생합니다.
        child: _pages[_selectedIndex],
      ),
      bottomNavigationBar: BottomNavigationBar(
        currentIndex: _selectedIndex,
        onTap: (index) {
          setState(() {
            _selectedIndex = index;
          });
        },
        items: const [
          BottomNavigationBarItem(icon: Icon(Icons.home), label: 'Home'),
          BottomNavigationBarItem(icon: Icon(Icons.settings), label: 'Settings'),
          BottomNavigationBarItem(icon: Icon(Icons.person), label: 'Profile'),
        ],
      ),
    );
  }
}

class _PageContent extends StatelessWidget {
  final IconData icon;
  final String label;
  const _PageContent({required this.icon, required this.label});

  @override
  Widget build(BuildContext context) {
    return Center(
      key: ValueKey(label), // PageTransitionSwitcher가 위젯을 구분하는 핵심 키
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Icon(icon, size: 80, color: Theme.of(context).primaryColor),
          const SizedBox(height: 20),
          Text(label, style: Theme.of(context).textTheme.headlineMedium),
        ],
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter/scheduler.dart';
import 'container_demo.dart'; // Step 2에서 생성
import 'fade_through_demo.dart'; // Step 3에서 생성

void main() {
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Animations Demo',
      theme: ThemeData(
        useMaterial3: true,
        colorScheme: ColorScheme.fromSeed(seedColor: Colors.blue),
      ),
      home: const TransitionsHomePage(),
    );
  }
}

class TransitionsHomePage extends StatefulWidget {
  const TransitionsHomePage({super.key});

  @override
  State<TransitionsHomePage> createState() => _TransitionsHomePageState();
}

class _TransitionsHomePageState extends State<TransitionsHomePage> {
  bool _slowAnimations = false;

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Material Transitions Demo')),
      body: Column(
        children: <Widget>[
          Expanded(
            child: ListView(
              children: <Widget>[
                _TransitionListTile(
                  title: 'Container Transform',
                  subtitle: 'OpenContainer (Detail View)',
                  onTap: () {
                    Navigator.of(context).push(MaterialPageRoute<void>(
                      builder: (BuildContext context) => const OpenContainerTransformDemo(),
                    ));
                  },
                ),
                _TransitionListTile(
                  title: 'Fade Through',
                  subtitle: 'FadeThroughTransition (Tab Switch)',
                  onTap: () {
                    Navigator.of(context).push(MaterialPageRoute<void>(
                      builder: (BuildContext context) => const FadeThroughTransitionDemo(),
                    ));
                  },
                ),
                // SharedAxisTransition, FadeScaleTransition 등 다른 데모 추가 가능
              ],
            ),
          ),
          const Divider(height: 0.0),
          SafeArea(
            child: SwitchListTile(
              value: _slowAnimations,
              onChanged: (bool value) async {
                setState(() { _slowAnimations = value; });
                // timeDilation을 사용하여 애니메이션 속도 제어
                timeDilation = _slowAnimations ? 20.0 : 1.0;
              },
              title: const Text('Slow animations (디버깅용)'),
            ),
          ),
        ],
      ),
    );
  }
}

